(* [comment removed for export] *)
(* [comment removed for export] *)
(* [comment removed for export] *)
Definition SS_STORE : Z := 0x093e60.

Definition store_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (lo PK SB Fr n : Z) (nj : nat) (m : word -> option byte) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (Fr + 1)) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (SSB, SSB + 8); (SSB_STORED, SSB_STORED + 4); (PK, PK + 8); (SB + 8 * Fr, SB + 8 * Fr + 8 * (n + 1))] m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ rw_cells bsegs m' SSB [C8 (wz (Fr + n + 1))]
    /\ rw_cells bsegs m' SSB_STORED [C4 (wz (Fr + n + 1))]
    /\ rw_cells bsegs m' PK [C8 (wz 0)]
    /\ (exists junk', u8arr bsegs m' (SB + 8 * Fr) junk' /\ length junk' = nj)
    /\ stk bsegs m' lo (bv_unsigned sp).

(* [comment removed for export] *)
Lemma land_m16 : forall x, 0 <= x < 2^64 -> Z.land x 18446744073709551600 = x - x mod 16.
Proof.
  intros x Hx. transitivity (Z.ldiff (Z.land x (Z.ones 64)) (Z.ones 4)).
  - rewrite Z.ldiff_land. rewrite <- Z.land_assoc. f_equal.
  - rewrite Z.land_ones, Z.mod_small by lia. rewrite Z.ldiff_ones_r by lia.
    rewrite Z.shiftl_mul_pow2, Z.shiftr_div_pow2 by lia. change (2^4) with 16. Z.div_mod_to_equations. lia.
Qed.

